    const current = getCurrentId();
    if (current) {
      await loadThread(current);
      await refreshActiveDocuments();
      updateExportConversationButton();
    } else {
      await newThread();
      await refreshActiveDocuments();
      updateExportConversationButton();
    }
  };

  void bootstrapApp();
})();
